/**
 * src/audio.js — Chrono Lab synthesized sound effects via Web Audio API.
 *
 * All sounds are generated by oscillators and noise; no external audio files.
 * The module hooks into window.CHRONO_EVENTS when loaded.
 * Browsers require a user gesture before AudioContext creation (first click).
 *
 * Member C — AI REQUIRED / AI ALLOWED
 */

let audioCtx = null;
let masterGain = null;
let muted = false;

/**
 * Initialise the AudioContext. Must be called from a user-gesture handler
 * (first click on Start / Watch Demo). Safe to call more than once.
 */
export function initAudio() {
  if (audioCtx) return;
  try {
    audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    masterGain = audioCtx.createGain();
    masterGain.gain.value = 1;
    masterGain.connect(audioCtx.destination);
  } catch (e) {
    console.warn('Chrono Lab Audio: Web Audio API unavailable.', e);
    audioCtx = null;
  }
}

/** Toggle global mute. Returns the new mute state. */
export function toggleMute() {
  if (!audioCtx) return false;
  muted = !muted;
  if (masterGain) {
    masterGain.gain.value = muted ? 0 : 1;
  }
  return muted;
}

/** @returns {boolean} current mute state. */
export function isMuted() { return muted; }

/* ---- helpers ---- */

function ensureCtx() {
  if (!audioCtx || audioCtx.state === 'closed') return false;
  if (audioCtx.state === 'suspended') {
    audioCtx.resume().catch(() => {});
  }
  return true;
}

/** Create a simple gain envelope: ramp from 0 -> value -> 0 over duration. */
function envelope(gain, startTime, value, attack, sustain, release) {
  gain.gain.setValueAtTime(0, startTime);
  gain.gain.linearRampToValueAtTime(value, startTime + attack);
  gain.gain.setValueAtTime(value, startTime + attack + sustain);
  gain.gain.linearRampToValueAtTime(0, startTime + attack + sustain + release);
}

function connectMaster(node) {
  if (masterGain) node.connect(masterGain);
  else if (audioCtx) node.connect(audioCtx.destination);
}

/* ---- sound effects ---- */

/** onRewind — descending pitch slide (time rewind feel) */
export function playRewind() {
  if (!ensureCtx()) return;
  const t = audioCtx.currentTime;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'sawtooth';
  osc.frequency.setValueAtTime(440, t);
  osc.frequency.exponentialRampToValueAtTime(80, t + 1.2);
  envelope(gain, t, 0.25, 0.05, 0.4, 0.6);
  osc.connect(gain);
  connectMaster(gain);
  osc.start(t);
  osc.stop(t + 1.2);
}

/** onCloneSpawn — rising echo */
export function playCloneSpawn() {
  if (!ensureCtx()) return;
  const t = audioCtx.currentTime;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'sine';
  osc.frequency.setValueAtTime(200, t);
  osc.frequency.exponentialRampToValueAtTime(1200, t + 0.6);
  envelope(gain, t, 0.2, 0.02, 0.1, 0.5);
  osc.connect(gain);
  connectMaster(gain);
  osc.start(t);
  osc.stop(t + 0.7);
}

/** onPlateActivate — clear confirm tone */
export function playPlateActivate() {
  if (!ensureCtx()) return;
  const t = audioCtx.currentTime;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'triangle';
  osc.frequency.setValueAtTime(880, t);
  osc.frequency.setValueAtTime(1100, t + 0.08);
  envelope(gain, t, 0.18, 0.01, 0.08, 0.25);
  osc.connect(gain);
  connectMaster(gain);
  osc.start(t);
  osc.stop(t + 0.35);
}

/** onLaserHit — low warning hum */
export function playLaserHit() {
  if (!ensureCtx()) return;
  const t = audioCtx.currentTime;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'square';
  osc.frequency.setValueAtTime(120, t);
  osc.frequency.setValueAtTime(90, t + 0.15);
  envelope(gain, t, 0.35, 0.01, 0.2, 0.4);
  osc.connect(gain);
  connectMaster(gain);
  osc.start(t);
  osc.stop(t + 0.6);
}

/** onCoreCollect — bright ascending arpeggio */
export function playCoreCollect() {
  if (!ensureCtx()) return;
  const t = audioCtx.currentTime;
  const notes = [523, 659, 784, 1047]; // C5 E5 G5 C6
  notes.forEach((freq, i) => {
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t + i * 0.1);
    envelope(gain, t + i * 0.1, 0.2, 0.02, 0.15, 0.3);
    osc.connect(gain);
    connectMaster(gain);
    osc.start(t + i * 0.1);
    osc.stop(t + i * 0.1 + 0.4);
  });
}

/** onDoorOpen — energy charge sound */
export function playDoorOpen() {
  if (!ensureCtx()) return;
  const t = audioCtx.currentTime;
  const osc = audioCtx.createOscillator();
  const gain = audioCtx.createGain();
  osc.type = 'sawtooth';
  osc.frequency.setValueAtTime(150, t);
  osc.frequency.linearRampToValueAtTime(600, t + 0.5);
  envelope(gain, t, 0.2, 0.05, 0.3, 0.4);
  osc.connect(gain);
  connectMaster(gain);
  osc.start(t);
  osc.stop(t + 0.8);
  // Add a second layer for "energy charge" feel
  const osc2 = audioCtx.createOscillator();
  const gain2 = audioCtx.createGain();
  osc2.type = 'sine';
  osc2.frequency.setValueAtTime(400, t);
  osc2.frequency.linearRampToValueAtTime(900, t + 0.5);
  envelope(gain2, t, 0.12, 0.05, 0.3, 0.4);
  osc2.connect(gain2);
  connectMaster(gain2);
  osc2.start(t);
  osc2.stop(t + 0.8);
}

/** onVictory — short victory melody */
export function playVictory() {
  if (!ensureCtx()) return;
  const t = audioCtx.currentTime;
  const melody = [523, 659, 784, 1047, 784, 1047, 1319]; // C E G C G C E
  melody.forEach((freq, i) => {
    const osc = audioCtx.createOscillator();
    const gain = audioCtx.createGain();
    osc.type = 'sine';
    osc.frequency.setValueAtTime(freq, t + i * 0.15);
    envelope(gain, t + i * 0.15, 0.22, 0.02, 0.2, 0.35);
    osc.connect(gain);
    connectMaster(gain);
    osc.start(t + i * 0.15);
    osc.stop(t + i * 0.15 + 0.45);
  });
}

/* ---- low ambient hum (optional, can be toggled) ---- */
let ambientNode = null;

export function startAmbient() {
  if (!ensureCtx() || ambientNode) return;
  const bufferSize = audioCtx.sampleRate * 4;
  const buffer = audioCtx.createBuffer(1, bufferSize, audioCtx.sampleRate);
  const data = buffer.getChannelData(0);
  for (let i = 0; i < bufferSize; i++) {
    // very low brown-ish noise
    data[i] = (Math.random() * 2 - 1) * Math.pow(i / bufferSize, 0.3);
  }
  const source = audioCtx.createBufferSource();
  source.buffer = buffer;
  source.loop = true;
  const gain = audioCtx.createGain();
  gain.gain.value = 0.02; // very quiet
  const filter = audioCtx.createBiquadFilter();
  filter.type = 'lowpass';
  filter.frequency.value = 150;
  source.connect(filter);
  filter.connect(gain);
  connectMaster(gain);
  source.start();
  ambientNode = { source, gain, filter };
}

export function stopAmbient() {
  if (!ambientNode) return;
  try { ambientNode.source.stop(); } catch (e) { /* ignore */ }
  ambientNode = null;
}

/* ---- install hooks on window.CHRONO_EVENTS ---- */

export function installAudioHooks() {
  const events = {
    onRewind: playRewind,
    onCloneSpawn: playCloneSpawn,
    onPlateActivate: playPlateActivate,
    onLaserHit: playLaserHit,
    onCoreCollect: playCoreCollect,
    onDoorOpen: playDoorOpen,
    onVictory: playVictory,
  };

  if (!window.CHRONO_EVENTS) {
    window.CHRONO_EVENTS = {};
  }

  Object.keys(events).forEach((key) => {
    const original = window.CHRONO_EVENTS[key];
    const handler = events[key];
    if (original) {
      // Chain: call original then audio
      window.CHRONO_EVENTS[key] = (...args) => {
        original(...args);
        handler(...args);
      };
    } else {
      window.CHRONO_EVENTS[key] = handler;
    }
  });
}
